#include <stdio.h>

int sum(int arr[], int n) {
    int total = 0;
    for (int i = 0; i < n; i++) {
        total += arr[i];
    }
    return total;
}

int main(void) {
    int data[] = {4, 8, 15, 16, 23, 42};
    printf("%d\n", sum(data, 6));   // 108
    return 0;
}

